static void sdio_reset(FAR struct sdio_dev_s *dev)
{
  FAR struct bk7258_sdio_s *priv = (FAR struct bk7258_sdio_s *)dev;

  sdio_reset_hw(priv);
  priv->data_active = false;
  priv->remaining = 0;
  priv->wake_events = 0;
}

